/**
 * cli-doctor — DSH Host half.
 *
 * A Cordis function plugin with zero third-party imports: every module it
 * touches comes from the `node:` builtin namespace. It owns one prefix route,
 * `/api/cli-doctor`, which exposes:
 *
 *   GET | HEAD /api/cli-doctor/health   200 { ok, version, busy }
 *   POST      /api/cli-doctor/check     runs bin/check.js --json --no-update
 *
 * The diagnosis itself is delegated to the vendored, read-only copy of the
 * repository's `bin/check.js` (generated by scripts/sync-shared.mjs). The
 * plugin never upgrades anything; it only reports.
 *
 * The route is fenced three ways (see isTrustedRequest): a loopback socket
 * address, a loopback Host authority, and a browser same-origin marker. The
 * marker branch that accepts the `dsh-auth-*` cookie exists because the DSH
 * Desktop shell serves the Web GUI from `dsh-app://app/` and forwards its
 * requests after deleting `Origin` and `sec-fetch-site` — the signed cookie it
 * attaches in their place is the only signal such a request carries.
 *
 * Testing seams (all optional, defaults are the production values): `spawn`,
 * `execPath`, `checkPath`, `timeoutMs`, `maxOutputBytes` and `logger` may be
 * passed through the plugin config object so tests never run a real diagnosis.
 *
 * @module dsh-cli-doctor/host
 */

import { spawn } from 'node:child_process'
import { readFileSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

/** Plugin name; the bundle id and the client half's loader id must match it. */
export const name = 'cli-doctor'

/** The route table lives on the host web server. */
export const inject = ['webServer']

/** Route prefix owned by this plugin. */
const API_PREFIX = '/api/cli-doctor'
const HEALTH_PATH = `${API_PREFIX}/health`
const CHECK_PATH = `${API_PREFIX}/check`

/** Hard cap on one diagnosis: eight minutes, then SIGTERM and a typed failure. */
const CHECK_TIMEOUT_MS = 8 * 60 * 1000

/** Hard cap on the report size; the real report is a few hundred KiB at most. */
const MAX_OUTPUT_BYTES = 24 * 1024 * 1024

/** stderr is only echoed into the host log, so keep just its tail. */
const MAX_STDERR_BYTES = 64 * 1024

/** Harness browser-auth cookie prefix minted by the host connection layer. */
const BROWSER_AUTH_COOKIE_PREFIX = 'dsh-auth-'

/** Package root: this file is <pkg>/src/host/index.js. */
const PKG_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..')

/* -------------------------------------------------------------------------- */
/* response helpers                                                           */
/* -------------------------------------------------------------------------- */

/**
 * Write one JSON response with the contract headers. HEAD responses carry the
 * status and headers but no body, per HTTP.
 * @param res - the ServerResponse (or a test double with writeHead/end).
 * @param status - HTTP status code.
 * @param body - JSON-serializable payload.
 * @param omitBody - true for HEAD.
 */
function writeJson(res, status, body, omitBody = false) {
  res.writeHead(status, {
    'content-type': 'application/json; charset=utf-8',
    'cache-control': 'no-store',
  })
  res.end(omitBody ? undefined : JSON.stringify(body))
}

/**
 * Write a failure response without ever throwing: a handler that throws is
 * turned into a 400 by the host web server, which would hide the real status.
 */
function safeWriteJson(res, status, body) {
  try {
    if (res.headersSent === true || res.writableEnded === true) {
      try { res.end() } catch { /* the socket is already gone */ }
      return
    }
    writeJson(res, status, body)
  } catch {
    /* nothing left to do: the response stream is unusable */
  }
}

/* -------------------------------------------------------------------------- */
/* loopback fence                                                             */
/* -------------------------------------------------------------------------- */

/** IPv4 127/8 predicate: four decimal octets, first == 127. */
function isIPv4Loopback(value) {
  const parts = value.split('.')
  return parts.length === 4 &&
    parts[0] === '127' &&
    parts.every(part => /^\d{1,3}$/.test(part) && Number(part) <= 255)
}

/** Whether a socket remote address names the loopback range. */
function isLoopbackAddress(address) {
  if (typeof address !== 'string' || address === '') return false
  const normalized = address.toLowerCase()
  if (normalized === '::1') return true
  if (normalized.startsWith('::ffff:')) return isIPv4Loopback(normalized.slice('::ffff:'.length))
  return isIPv4Loopback(normalized)
}

/** Whether a URL hostname names a loopback authority. */
function isLoopbackHostname(hostname) {
  if (hostname === 'localhost' || hostname === '[::1]') return true
  return isIPv4Loopback(hostname)
}

/**
 * Parse a Host header as a bare loopback authority, or null when it is not one.
 * Rejects userinfo, paths, queries and non-canonical whitespace so a forged
 * authority cannot smuggle a non-loopback name past the check.
 */
function parseLoopbackAuthority(host) {
  if (typeof host !== 'string' || host === '' || host.trim() !== host) return null
  let url
  try {
    url = new URL(`http://${host}`)
  } catch {
    return null
  }
  if (url.username !== '' || url.password !== '') return null
  if (url.pathname !== '/' || url.search !== '' || url.hash !== '') return null
  if (!isLoopbackHostname(url.hostname)) return null
  return url
}

/** Whether a Cookie header carries a host browser-auth credential. */
function carriesBrowserAuthCookie(header) {
  if (typeof header !== 'string' || header === '') return false
  return header.split(';').some(segment => segment.trim().startsWith(BROWSER_AUTH_COOKIE_PREFIX))
}

/**
 * Browser signal, not an authority check: a marker-less request (bare curl) is
 * refused here, while a request that carries any of the three markers falls
 * through to the socket/Host/origin checks that carry the real authority.
 */
function browserSameOriginMarker(headers) {
  if (headers['sec-fetch-site'] === 'same-origin') return true
  if (typeof headers.origin === 'string') return true
  return carriesBrowserAuthCookie(headers.cookie)
}

/** Normalize a possibly malformed request's headers to an object. */
function requestHeaders(req) {
  const headers = req === null || typeof req !== 'object' ? undefined : req.headers
  return headers !== null && typeof headers === 'object' ? headers : {}
}

/**
 * Route fence. Every branch below must hold:
 *   - the connection is loopback (127/8, ::1, ::ffff:127/8);
 *   - Host is a loopback authority, and Origin — when present — is same-origin
 *     with it (a cross-site fetch is refused outright);
 *   - the request carries a browser same-origin marker.
 * @param req - the IncomingMessage (or a test double).
 */
function isTrustedRequest(req) {
  const headers = requestHeaders(req)
  if (!browserSameOriginMarker(headers)) return false
  const remoteAddress = req !== null && typeof req === 'object' && req.socket !== null && typeof req.socket === 'object'
    ? req.socket.remoteAddress
    : undefined
  if (!isLoopbackAddress(remoteAddress)) return false
  const hostUrl = parseLoopbackAuthority(headers.host)
  if (hostUrl === null) return false
  if (headers['sec-fetch-site'] === 'cross-site') return false
  const origin = headers.origin
  if (origin !== undefined) {
    if (typeof origin !== 'string') return false
    let originUrl
    try {
      originUrl = new URL(origin)
    } catch {
      return false
    }
    if (originUrl.host !== hostUrl.host) return false
  }
  return true
}

/* -------------------------------------------------------------------------- */
/* diagnosis subprocess                                                       */
/* -------------------------------------------------------------------------- */

/** Structured diagnosis failure: a stable machine-readable code plus detail. */
class CheckFailure extends Error {
  constructor(code, detail) {
    super(detail === undefined ? code : `${code}: ${detail}`)
    this.name = 'CheckFailure'
    this.code = code
    this.detail = detail
  }
}

function messageOf(error) {
  if (error instanceof Error) return error.message
  return String(error)
}

function toBuffer(chunk) {
  return Buffer.isBuffer(chunk) ? chunk : Buffer.from(String(chunk))
}

/** Default logger: failures go to the host process stderr, never to the client. */
function defaultLogger(message) {
  try {
    process.stderr.write(`[cli-doctor] ${message}\n`)
  } catch {
    /* stderr may be closed while the host shuts down */
  }
}

/**
 * Resolve the effective plugin options. Every value has a production default;
 * the config object only exists so tests can replace the subprocess seam.
 */
function resolveOptions(config) {
  const cfg = config !== null && typeof config === 'object' ? config : {}
  const checkPath = typeof cfg.checkPath === 'string' && cfg.checkPath !== ''
    ? cfg.checkPath
    : (typeof process.env.CLI_DOCTOR_CHECK_PATH === 'string' && process.env.CLI_DOCTOR_CHECK_PATH !== ''
        ? process.env.CLI_DOCTOR_CHECK_PATH
        : path.join(PKG_ROOT, 'bin', 'check.js'))
  return {
    pkgRoot: PKG_ROOT,
    version: packageVersion(PKG_ROOT),
    checkPath,
    execPath: typeof cfg.execPath === 'string' && cfg.execPath !== '' ? cfg.execPath : process.execPath,
    spawn: typeof cfg.spawn === 'function' ? cfg.spawn : spawn,
    timeoutMs: Number.isFinite(cfg.timeoutMs) && cfg.timeoutMs > 0 ? cfg.timeoutMs : CHECK_TIMEOUT_MS,
    maxOutputBytes: Number.isFinite(cfg.maxOutputBytes) && cfg.maxOutputBytes > 0
      ? cfg.maxOutputBytes
      : MAX_OUTPUT_BYTES,
    logger: typeof cfg.logger === 'function' ? cfg.logger : defaultLogger,
  }
}

/** Log a failure to the host stderr (or the injected logger) without throwing. */
function log(options, message) {
  try {
    options.logger(message)
  } catch {
    /* a broken logger must never break a request */
  }
}

/**
 * Run one diagnosis. Resolves with the parsed `check.js --json` report and
 * rejects with a CheckFailure for every failure mode: spawn error, non-zero
 * exit, timeout, output over the cap, or unparseable JSON.
 */
function runDiagnosis(options, state) {
  return new Promise((resolve, reject) => {
    let child
    try {
      child = options.spawn(
        options.execPath,
        [options.checkPath, '--json', '--no-update'],
        { cwd: options.pkgRoot, env: process.env },
      )
    } catch (error) {
      reject(new CheckFailure('spawn-error', messageOf(error)))
      return
    }
    if (child === null || typeof child !== 'object' || typeof child.on !== 'function') {
      reject(new CheckFailure('spawn-error', 'spawn returned no child process'))
      return
    }

    const stdoutChunks = []
    const stderrChunks = []
    let stdoutBytes = 0
    let stderrBytes = 0
    let settled = false
    let timer = null

    const terminate = () => {
      try {
        if (typeof child.kill === 'function') child.kill('SIGTERM')
      } catch (error) {
        log(options, `failed to terminate check.js: ${messageOf(error)}`)
      }
    }

    const stopTimer = () => {
      if (timer !== null) {
        clearTimeout(timer)
        timer = null
      }
    }

    const detach = () => {
      try { child.stdout?.off?.('data', onStdout) } catch { /* already gone */ }
      try { child.stderr?.off?.('data', onStderr) } catch { /* already gone */ }
      try { child.off?.('close', onClose) } catch { /* already gone */ }
      try { child.off?.('error', onError) } catch { /* already gone */ }
    }

    const fail = (code, detail) => {
      if (settled) return
      settled = true
      stopTimer()
      detach()
      reject(new CheckFailure(code, detail))
    }

    /**
     * Stop the run without settling the promise: the fiber that owned the
     * request is being disposed, so nobody is left to answer. Clearing the
     * timer here is what keeps disposal from leaving a dangling timeout behind.
     */
    const cancel = () => {
      if (settled) return
      settled = true
      stopTimer()
      detach()
      terminate()
    }

    const succeed = (report) => {
      if (settled) return
      settled = true
      stopTimer()
      detach()
      resolve(report)
    }

    function onStdout(chunk) {
      if (settled) return
      const buffer = toBuffer(chunk)
      stdoutBytes += buffer.length
      if (stdoutBytes > options.maxOutputBytes) {
        terminate()
        fail('output-too-large', `stdout exceeded ${options.maxOutputBytes} bytes`)
        return
      }
      stdoutChunks.push(buffer)
    }

    function onStderr(chunk) {
      if (settled) return
      const buffer = toBuffer(chunk)
      stderrChunks.push(buffer)
      stderrBytes += buffer.length
      while (stderrChunks.length > 1 && stderrBytes - stderrChunks[0].length > MAX_STDERR_BYTES) {
        stderrBytes -= stderrChunks.shift().length
      }
    }

    function onError(error) {
      fail('spawn-error', messageOf(error))
    }

    function onClose(code, signal) {
      if (settled) return
      const stderr = Buffer.concat(stderrChunks).toString('utf8').trim()
      if (code !== 0) {
        const reason = code === null || code === undefined ? `signal-${signal === null || signal === undefined ? 'unknown' : signal}` : `exit-${code}`
        fail(reason, stderr === '' ? 'check.js failed without stderr' : `check.js stderr: ${stderr}`)
        return
      }
      let report
      try {
        report = JSON.parse(Buffer.concat(stdoutChunks).toString('utf8'))
      } catch (error) {
        fail('invalid-json', `check.js stdout is not valid JSON (${messageOf(error)})`)
        return
      }
      succeed(report)
    }

    if (child.stdout !== null && child.stdout !== undefined && typeof child.stdout.on === 'function') {
      child.stdout.on('data', onStdout)
    }
    if (child.stderr !== null && child.stderr !== undefined && typeof child.stderr.on === 'function') {
      child.stderr.on('data', onStderr)
    }
    child.on('error', onError)
    child.on('close', onClose)

    // Exposed so fiber disposal can stop an in-flight diagnosis.
    state.current = { child, terminate, cancel }

    timer = setTimeout(() => {
      terminate()
      fail('timeout', `check.js did not finish within ${options.timeoutMs} ms`)
    }, options.timeoutMs)
  })
}

/* -------------------------------------------------------------------------- */
/* request handling                                                           */
/* -------------------------------------------------------------------------- */

/**
 * Pathname of a request target, parsed exactly like the host web server's own
 * route matcher (`new URL(req.url, 'http://x').pathname`) so a target the
 * router matched can never fall through as not-found here: origin-form and
 * absolute-form targets, queries and fragments all resolve to the same path.
 */
function requestPath(req) {
  const url = req !== null && typeof req === 'object' ? req.url : undefined
  if (typeof url !== 'string' || url === '') return ''
  try {
    return new URL(url, 'http://x').pathname
  } catch {
    const cut = url.indexOf('?')
    return cut === -1 ? url : url.slice(0, cut)
  }
}

function requestMethod(req) {
  const method = req !== null && typeof req === 'object' ? req.method : undefined
  return typeof method === 'string' ? method.toUpperCase() : ''
}

/** Package version for the health payload; 'unknown' if package.json is unreadable. */
function packageVersion(pkgRoot) {
  try {
    const pkg = JSON.parse(readFileSync(path.join(pkgRoot, 'package.json'), 'utf8'))
    return pkg !== null && typeof pkg === 'object' && typeof pkg.version === 'string' && pkg.version !== ''
      ? pkg.version
      : 'unknown'
  } catch {
    return 'unknown'
  }
}

/**
 * The one registered route handler. It is intentionally synchronous: it kicks
 * off an async dispatch and converts every rejection into a typed 500, so no
 * exception can ever escape into the host web server (which would turn it into
 * a 400 and hide the real failure).
 */
function handleRequest(req, res, state) {
  let pending
  try {
    pending = dispatch(req, res, state)
  } catch (error) {
    failRequest(res, state, error)
    return
  }
  if (pending !== null && typeof pending === 'object' && typeof pending.then === 'function') {
    pending.catch(error => { failRequest(res, state, error) })
  }
}

async function dispatch(req, res, state) {
  const pathname = requestPath(req)
  if (pathname === HEALTH_PATH) {
    if (requestMethod(req) !== 'GET' && requestMethod(req) !== 'HEAD') {
      writeJson(res, 405, { ok: false, error: 'method' })
      return
    }
    if (!isTrustedRequest(req)) {
      writeJson(res, 403, { ok: false, error: 'forbidden' })
      return
    }
    writeJson(res, 200, {
      ok: true,
      version: state.options.version,
      busy: state.checking,
    }, requestMethod(req) === 'HEAD')
    return
  }

  if (pathname === CHECK_PATH) {
    if (requestMethod(req) !== 'POST') {
      writeJson(res, 405, { ok: false, error: 'method' })
      return
    }
    if (!isTrustedRequest(req)) {
      writeJson(res, 403, { ok: false, error: 'forbidden' })
      return
    }
    await handleCheck(res, state)
    return
  }

  writeJson(res, 404, { ok: false, error: 'not-found' })
}

/** Single-flight diagnosis: the second concurrent request is refused at once. */
async function handleCheck(res, state) {
  if (state.checking) {
    writeJson(res, 409, { ok: false, error: 'busy' })
    return
  }
  state.checking = true
  try {
    const report = await runDiagnosis(state.options, state)
    writeJson(res, 200, { ok: true, report, checkedAt: new Date().toISOString() })
  } catch (error) {
    const reason = error instanceof CheckFailure ? error.code : 'internal'
    log(state.options, `diagnosis failed (${reason}): ${messageOf(error)}`)
    safeWriteJson(res, 500, { ok: false, error: reason })
  } finally {
    state.checking = false
    state.current = null
  }
}

/** Last-resort failure path for unexpected errors thrown outside handleCheck. */
function failRequest(res, state, error) {
  const reason = error instanceof CheckFailure
    ? error.code
    : (error instanceof Error && error.message !== '' ? error.message : 'internal')
  log(state.options, `request failed (${reason}): ${messageOf(error)}`)
  safeWriteJson(res, 500, { ok: false, error: reason })
}

/** Stop an in-flight diagnosis when the plugin fiber is disposed. */
function killCurrent(state) {
  const current = state.current
  state.current = null
  if (current === null || current === undefined) return
  try {
    if (typeof current.cancel === 'function') current.cancel()
    else current.terminate()
  } catch {
    /* the child is already gone */
  }
}

/* -------------------------------------------------------------------------- */
/* plugin                                                                     */
/* -------------------------------------------------------------------------- */

/**
 * Cordis plugin entry: register the `/api/cli-doctor` prefix route and bind it
 * (plus any in-flight diagnosis) to the fiber lifecycle.
 * @param ctx - the plugin context, providing `webServer` and `effect`.
 * @param config - optional overrides; defaults are the production values.
 */
export function apply(ctx, config) {
  const options = resolveOptions(config)
  const state = { options, checking: false, current: null }
  const handler = (req, res) => { handleRequest(req, res, state) }

  ctx.effect(() => {
    const disposeRoute = ctx.webServer.register({ kind: 'prefix', path: API_PREFIX, handler })
    return () => {
      try {
        if (typeof disposeRoute === 'function') disposeRoute()
      } catch (error) {
        log(options, `route disposal failed: ${messageOf(error)}`)
      }
      killCurrent(state)
    }
  }, 'cli-doctor: routes')
}
